internal object DuaAmDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("የመጀመሪያውን ፍሬ ማየት", "አሏህ ሆይ በፍሬያችን ባርክልን በከተማችንም ባርክልን በሰዓታችን እና በጭቃችን (መለኪያ) ባርክልን።", "የወቅቱን የመጀመሪያ ፍሬ በማየት ላይ.", "በአቅርቦት እና በከተማ ውስጥ የበረከት ዱዓ።"),
        "dua_good_news" to DuaText("ደስ የሚል ዜና", "ምስጋና ሁሉ በችሮታው መልካም ነገሮች ለተጠናቀቁት ለአላህ ይገባው።", "የምስራች በመቀበል ላይ (እና የምስጋና ስግደትን ስገዱ)።", "ነቢዩ ﷺ የሚወዱትን ነገር አይተው እንዲህ ብለው ነበር።"),
        "dua_looking_mirror" to DuaText("በመስታወት ውስጥ በመመልከት ላይ", "አላህ ሆይ መልኬን እንዳሳመርከው ሁሉ እኔም ባህሪዬን አሳምርልኝ።", "በመስታወት ውስጥ ሲመለከቱ.", "ነብዩ ﷺ ይህንን ዱዓ ያደርጉ ነበር (መስታወት ሳይነሳ እንኳን የተቋቋመ ነው)።"),
        "dua_rabbana_taqabbal" to DuaText("ድርጊቶችን መቀበል", "ጌታችን ሆይ ይህን ከእኛ ተቀበል; አንተ ሰሚው ዐዋቂው ነህና። ንስሐችንንም ተቀበል; አንተ ጸጸትን ተቀባይ አዛኝ ነህና።", "ኢብራሂም እና ኢስማኢል (AS) ካዕባን ሲገነቡ ጠየቁ።", "ከእያንዳንዱ መልካም ስራ በኋላ ተቀባይነት ለማግኘት ዱዓ።"),
        "dua_muawwidhat" to DuaText("ሦስቱ ቁልስ (ሙአውውዳት)", "(ሱረቱ አል-ኢኽላስ) በላቸው፡- እርሱ አላህ አንድ ነው። የበቃው አላህ። አይወልድም አይወለድም። ለእርሱም ምንም ብጤ የለም።\n\n(ሱረቱ አል-ፈላቅ) በላቸው፡- እኔ በነጋ ጌታ ከፈጠረው መጥፎ ነገር፣ ከጨለማዎችም በረጋ ጊዜ፣ ቋጠሮ ከሚነፍሱ ሰዎች ክፋት፣ በምቀኝነትም ጊዜ ከሚቀናው ክፉ ነገር እጠበቃለሁ።\n\n(ሱረቱ አን-ናስ) በላቸው፡- ከጋኔንና ከሰዎች መካከል በሰዎች ልብ ውስጥ ከሚንሾካሾከ ከጠፊው ሹክሹክታ፣ የሰው ልጆች ንጉሥ፣ የሰው አምላክ በሆነው ጌታ እጠበቃለሁ።", "ሶስቱ ሱራዎች በየቀኑ ጠዋት እና ማታ ሶስት ጊዜ እና ከመተኛታቸው በፊት እጆቻቸውን ይንፉ እና በሰውነት ላይ ያብሷቸው።", "ጠዋት እና ማታ ሶስት ጊዜ እነሱን ማንበብ በሁሉም ነገር ላይ በቂ ነው."),
        "dua_sabr" to DuaText("ለትዕግስት እና ጽናት።", "ጌታችን ሆይ በኛ ላይ ትዕግስትን አፍስስ እግሮቻችንንም አፅናና በከሓዲዎችም ሕዝቦች ላይ እርዳን።", "በችግር እና በግጭት ጊዜ።", "የጣላት ጦር ዱዓ።"),
        "dua_rabbana_innana_amanna" to DuaText("ይቅርታ እና ከእሳት ጥበቃ", "ጌታችን አምነናል ኃጢአታችንንም ይቅር በለን ከእሳትም ቅጣት ጠብቀን።", "የቁርዓን ዱአ።", "አላህን ከሚፈሩ ባህሪያት መካከል የተጠቀሰው ዱዓ።"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("በጉዳያችን ውስጥ ያለው መመሪያ (አሻብ አል-ካህፍ)", "ጌታችን ሆይ ከራስህ የሆነን እዝነት ስጠን በጉዳያችንም ትክክለኛ መሪን አዘጋጅልን።", "የዋሻው ሰዎች ዱዓ።", "በውሳኔዎች እና በአስቸጋሪ ሁኔታዎች ውስጥ መመሪያ."),
        "dua_musa_faqir" to DuaText("የሙሳ ዱዓ (AS) ለዝግጅት", "ጌታዬ ሆይ እኔ ወደኔ ካወረድከኝ ከመልካም ነገር ሁሉ እፈልጋለሁ።", "አቅርቦትን እና መልካምን መፈለግ - የሙሳ ዱአ (AS) በማድያን።", "ከዚህ ዱዓ በኋላ አላህ ለሙሳ (AS) ቤት፣ ስራ እና ሚስት ሰጠው።"),
        "dua_ayyub" to DuaText("የአዩብ (AS) ዱዓ በህመም", "(ጌታዬ) ጉዳት ነካኝ፤ አንተም ከአዛኞች በጣም አዛኝ ነህ።", "በህመም እና በህመም.", "አላህ የአዩብን ስቃይ (AS) አስወገደ።"),
        "dua_husn_khatimah" to DuaText("ሙስሊም ሆነህ መሞት (ዩሱፍ ዐ.ሰ)", "የሰማይና የምድር ፈጣሪ አንተ በቅርቢቱም ሆነ በመጨረሻይቱ ዓለም ረዳቴ ነህ። ሙስሊም ሆኜ ልሙትና ከጻድቃን ጋር ተባበረኝ።", "ለመልካም መጨረሻ ዱአ።", "የነቢዩ ዩሱፍ ዱአ (AS)"),
        "dua_shaitan_hamazat" to DuaText("ከሰይጣናት ሹክሹክታ መሸሸጊያ", "ጌታዬ ሆይ ከሰይጣናት ሹክሹክታ በአንተ እጠበቃለሁ ወደኔ እንዳይቀርቡኝ ጌታዬ ባንተ እጠበቃለሁ።", "ከሰይጣን ሹክሹክታ መሸሽ።", "መጠጊያ ፍለጋ የቁርዓን ዱዓ።"),
        "dua_bad_character" to DuaText("ከመጥፎ ባህሪ መሸሽ", "አላህ ሆይ ከመጥፎ ባህሪ፣ ከመጥፎ ስራ እና ከመጥፎ ምኞት በአንተ እጠበቃለሁ።", "ከመጥፎ ባህሪ, ተግባሮች እና ፍላጎቶች መሸሽ.", "ከነብዩ የመሸሸጊያ ዱዓ ﷺ።"),
        "dua_zawal_nimah" to DuaText("ከበረከት ማጣት መሸሸጊያ", "አላህ ሆይ ፀጋህን ከማጣት፣ ከሰጠኸው ደህንነት ለውጥ፣ ከድንገተኛ ቅጣትህ እና ከማስከፋት በአንተ እጠበቃለሁ።", "በረከቶችን ከማጣት እና ከድንገተኛ አደጋ መሸሽ።", "የነቢዩ ዱአ ﷺ።"),
        "dua_useless_knowledge" to DuaText("ከማይጠቅም እውቀት መሸሽ", "አላህ ሆይ ከማይጠቅም እውቀት፣ከማይፈራ ልብ፣ከማትጠግብ ነፍስ፣ከማይመለስ ዱዓ በአንተ እጠበቃለሁ።", "አላህን ከመፍራት ከማይጠቅም እውቀትና ልብ መሸሸግ።", "ከነብዩ የመሸሸጊያ ዱዓ ﷺ።"),
        "dua_beneficial_knowledge" to DuaText("ጠቃሚ እውቀት እና ሃላል ሪዝቅ", "አላህ ሆይ ጠቃሚ እውቀትን፣ ንፁህ ሲሳይን እና ተቀባይነት ያላቸውን ስራዎችን እጠይቅሃለሁ።", "ከፈጅር ሶላት በኋላ።", "ነቢዩ ﷺ ከፈጅር ሰላም በኋላ እንዲህ አሉ።"),
        "dua_leprosy_diseases" to DuaText("ከከባድ በሽታዎች መሸሸጊያ", "አሏህ ሆይ ከ vitiligo ፣ እብደት ፣ ደዌ እና ከመጥፎ በሽታዎች በአንተ እጠበቃለሁ።", "ከከባድ በሽታዎች መከላከል.", "ጤናን ለመጠበቅ የሱና ዱዓ።"),
        "dua_fear_people" to DuaText("ጠላቶችን ወይም ጨቋኞችን መፍራት", "አሏህ ሆይ በፊታቸው እናደርግሃለን ከክፋታቸውም በአንተ እንጠበቃለን።", "የሰዎችን ወይም የአንድን ሰው ጉዳት በሚፈሩበት ጊዜ።", "ነብዩ ﷺ ህዝብን ሲፈሩ እንዲህ አሉ።"),
        "dua_shirk_protection" to DuaText("ከተደበቀ ሺርክ ጥበቃ", "አላህ ሆይ ምንም ነገር እያወቅኩ ካንተ ጋር እንዳላጋራ በአንተ እጠበቃለሁ፣ ሳላውቅም ለሰራሁት ምህረትህን እጠይቃለሁ።", "ከማሳየት እና ከተደበቀ ሽርክ ለመዳን።", "ከጉንዳን ሾልኮል ይልቅ የተደበቀ ሽርክ በጣም የተደበቀ ነው።"),
        "dua_rain" to DuaText("ዝናብ ሲዘንብ", "አላህ ሆይ ጠቃሚ ዝናብን ላክ።", "ዝናብ በሚዘንብበት ጊዜ.", "ዝናብ ዱዓ የሚቀበልበት ጊዜ ነው።"),
        "dua_after_rain" to DuaText("ከዝናብ በኋላ", "በአላህ ችሮታ እና እዝነቱ ዝናብ ሰጠን።", "ከዝናብ በኋላ.", "ይህን የሚል በአላህ ያመነ ነው።"),
        "dua_istisqa" to DuaText("ዝናብ መጠየቅ (ኢስቲስካ)", "አላህ ሆይ ዝናብን (ሶስት ጊዜ) ላክልን።", "ዝናብ በማይኖርበት ጊዜ.", "ነብዩ ﷺ ይህንን ዱዓ ያደረጉት በአርብ ስብከት ላይ ነው እናም ዘነበ።"),
        "dua_heavy_rain" to DuaText("ከመጠን በላይ ዝናብ", "አላህ ሆይ (ይውደቅ) በዙሪያችን እንጂ በኛ ላይ አይደለም።", "በጣም ብዙ ዝናብ በሚኖርበት ጊዜ.", "ደመናዎቹ በነብዩ ዱአ ﷺ ተንቀሳቀሱ።"),
        "dua_wind" to DuaText("ነፋሱ ሲነፍስ", "አላህ ሆይ መልካሙን፣ በውስጧ ያለውን መልካም ነገር እና የተላከበትን መልካም ነገር እጠይቅሃለሁ፣ ከክፉው፣ በውስጡ ካለው መጥፎ ነገር እና ከተላከበት መጥፎ ነገር በአንተ እጠበቃለሁ።", "ኃይለኛ ነፋስ ወይም አውሎ ነፋስ ሲነፍስ.", "ነቢዩ ﷺ ይህንን ዱዓ ያደረጉት በማዕበል ወቅት ነበር።"),
        "dua_thunder" to DuaText("ነጎድጓድ መስማት", "ነጎድጓዱም በምስጋናው የሚያከብረው ለመላእክትም እርሱን ከመፍራት የተነሳ ክብር ይገባው።", "ነጎድጓድ ሲሰማ - የ አብዱላህ ኢብኑ አዝ-ዙበይር ልምምድ (RA).", "ከሱረቱ አር-ራድ (13፡13) የተወሰደ።"),
        "dua_new_moon" to DuaText("አዲስ ጨረቃን ማየት", "አሏህ ሆይ ይህች ጨረቃ በላያችን ላይ በበረከት ፣በእምነት ፣በደህንነት እና በእስልምና ትውጣልን። (ጨረቃ ሆይ) ጌታዬና ጌታችሁ አላህ ነው።", "አዲስ ጨረቃን በማየት ላይ.", "ለእያንዳንዱ አዲስ ወር የሱና ዱዓ።"),
        "dua_janaza_adult" to DuaText("ጀናዛ ሶላት (አዋቂ)", "አሏህ ሆይ ለህይወታችን እና ለሞቱት ወገኖቻችን፣ ያሉትንና የሌሉትን፣ ታናናሾቻችንንና አዛውንቶቻችንን፣ ወንዶቻችንንና ሴቶቻችንን ይቅር በል። አሏህ ሆይ ከኛ ህያው ያደረግከውን ሰው በኢስላም ላይ ህያው አድርገህ የሞትከውንም ሰው በእምነት ግደለው።", "ከሶስተኛው ተክቢር የቀብር ሶላት በኋላ።", "ለሟች ጎልማሳ የሱና ዱዓ።"),
        "dua_janaza_child" to DuaText("ጀናዛ ሶላት (ልጅ)", "አሏህ ሆይ ለኛ ቀዳሚ (አስተናጋጅ) አድርገን፣ ምንዳና ሀብት አድርገን፤ አማላጅነታችንም ተቀባይነት ያለው አድርገን።", "በሕፃን የቀብር ጸሎት (ለሴት ልጅ 'ኢጅልሀ' ትላለች።)", "በሐነፊዎች የተተገበረው የሱና ዱዓ።"),
        "dua_mayyit_awf" to DuaText("ለሟች ዝርዝር ዱዓ", "አላህ ሆይ ይቅር በለው፣ እዘንለት፣ ምህረትን ስጠው እና ይቅር በለው። አቀባበሉን ያከበረ፣ መቃብሩንም ያሰፋው፣ በውሀ፣ በበረዶና በበረዶ እጠበው፣ ነጭ ልብስ ከቆሻሻ እንደሚነጻ ከሀጢያት አንጻው።", "በቀብር ጸሎት ወይም ለሟቹ.", "አውፍ ኢብኑ ማሊክ (RA) ያ ሟች ሰው ቢሆን ተመኘ።"),
        "dua_visiting_graves" to DuaText("መቃብሮችን መጎብኘት", "ሰላም ለናንተ ይሁን የነዚህ ቤቶች አማኞች እና ሙስሊም ነዋሪዎች ሆይ! እኛም አላህ ከፈቀደ እንቀላቅላችኋለን። ለኛም ለናንተም አላህን እለምናለሁ።", "ወደ መቃብር ሲገቡ.", "መቃብርን መጎብኘት ሞትን እና የመጨረሻውን ዓለም ያስታውሰዋል።"),
        "dua_closing_eyes" to DuaText("የሟቹን ዓይኖች ሲዘጉ", "አላህ ሆይ ይቅር በላቸው (ስም)፣ ደረጃውን ከተመሩት መካከል ከፍ አድርግ፣ ከተዋቸው ሰዎች መካከል ተተኪው ሁን። እኛንም እርሱንም ይቅር በለን የዓለማት ጌታ ሆይ; መቃብሩን አሰፋና በብርሃን ሙላው።", "የሟቹን ዓይኖች ሲዘጉ (ስሙን በመጥቀስ).", "ነቢዩ ﷺ ይህንን ዱዓ ለአቡ ሰላማ (RA) አድርገዋል።"),
        "dua_condolence" to DuaText("ማዘን (ታዚያ)", "የወሰደው ነገር የአላህ ብቻ ነው። የሰጠውም የርሱ ብቻ ነው። ነገሩም ሁሉ በእርሱ ዘንድ የተወሰነ ጊዜ አለው። ታገስም፤ ምንዳንም ተስፋ ጠብቅ።", "ከሞት በኋላ ለቤተሰብ መፅናናትን መስጠት.", "ነቢዩ ﷺ ይህንን መልእክት ወደ ሴት ልጃቸው ልኳል።"),
        "dua_placing_in_grave" to DuaText("ሟቹን በመቃብር ውስጥ ማስቀመጥ", "በአላህ ስም እና በአላህ መልእክተኛ መንገድ ﷺ።", "ሟቹን ወደ መቃብር ሲወርድ.", "የቀብር ሱና ዱዓ።"),
        "dua_sneezing" to DuaText("ማስነጠስ", "ምስጋና ሁሉ ለአላህ ነው። - አላህ ይዘንልህ። - አላህ ይምራህ ጉዳዮችህን ያስተካክል።", "በማስነጠስ ላይ; ሰሚው 'ይርሀሙካላህ' ይላል፣ ከዚያም ያስነጠሰው ይመልሳል።", "አንድ ሙስሊም በሌላው ሙስሊም ላይ ካለው መብቶች አንዱ ነው።"),
        "dua_toilet_enter" to DuaText("ሽንት ቤት ውስጥ መግባት", "በአላህ ስም። አላህ ሆይ ከወንድና ከሴት ርኩስ ጂን ባንተ እጠበቃለሁ።", "በግራ እግር ወደ መጸዳጃ ቤት ከመግባትዎ በፊት.", "ቢስሚላህ በጂንና በሰው መካከል መከታ ይሆናል።"),
        "dua_toilet_exit" to DuaText("ከመጸዳጃ ቤት መውጣት", "(አላህ ሆይ) ምህረትህን እሻለሁ።", "በቀኝ እግር ከመጸዳጃ ቤት ሲወጡ.", "ነብዩ ﷺ ከመጸዳጃ ቤት ሲወጡ እንዲህ ብለዋል ።"),
        "dua_thanking" to DuaText("ሰው ማመስገን", "አላህ መልካም ምንዳችሁን ይክፈላችሁ።", "አንድ ሰው ሞገስ ሲያደርግልዎ።", "ይህን የሚናገር ሁሉ ምስጋናውን ገልጿል።"),
        "dua_love_for_allah" to DuaText("አንድ ሰው 'ለአላህ ብዬ እወዳችኋለሁ' ሲል", "ለእርሱ ስል የወደዳችሁኝ እርሱ (አላህ) ይውደዳችሁ።", "አንድ ሰው 'ለአላህ ብዬ እወድሃለሁ' ሲል።", "የሱና መልስ ለአላህ ብሎ ለፍቅር።"),
        "dua_seeing_muslim_smile" to DuaText("ሰላምታ (ሰላም)", "ሰላም ለናንተ ይሁን የአላህ እዝነት እና በረከቶቹ።", "ከሙስሊም ጋር ሲገናኙ.", "ሙሉ ሰላም ማለት ሠላሳ መልካም ሥራዎችን ያስገኛል።"),
        "dua_dressing" to DuaText("መልበስ", "ይህን በለበሰኝና በለገሰኝ ያለ ምንም ጉልበትና ጉልበት ለሰጠኝ አላህ ምስጋና ይገባው።", "ሲለብሱ.", "ያለፈው ኃጢአት ይቅርታ የምስራች ።"),
    )
}
